// /frontend-react/src/components/HeaderBar.js (REVISED for Max Text Flow)

import React from 'react';

const HeaderBar = ({ title, onBackClick, onMenuClick, isEasyMode }) => (
    <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '15px 10px', // Reduced horizontal padding
        backgroundColor: '#f8f9fa', 
        borderBottom: '1px solid #e0e0e0',
        position: 'relative',
        position: 'sticky',
        top: 0,
        zIndex: 5,
    }}>
        {/* Placeholder/Back Button Group (Left) */}
        <div style={{ width: '35px', flexShrink: 0, visibility: onBackClick ? 'visible' : 'hidden' }}>
            {onBackClick && (
                <button
                    onClick={onBackClick}
                    style={{
                        padding: '5px', // Smaller padding
                        backgroundColor: 'transparent',
                        border: 'none',
                        borderRadius: '50%',
                        cursor: 'pointer',
                        fontSize: isEasyMode ? '28px' : '18px', // Smaller icon size
                        color: '#333',
                    }}
                    onMouseOver={e => e.currentTarget.style.backgroundColor = '#ddd'}
                    onMouseOut={e => e.currentTarget.style.backgroundColor = 'transparent'}
                >
                    <span role="img" aria-label="Back">◀️</span>
                </button>
            )}
        </div>
        
        {/* Title (Center) */}
        <h2 style={{
            fontSize: isEasyMode ? '32px' : '22px', // Slightly increased font size for priority
            margin: '0 5px',
            color: '#333',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
            flexGrow: 1, 
            textAlign: 'center',
        }}>
            {title}
        </h2>
        
        {/* Placeholder/Menu Icon Group (Right) */}
        <div style={{ width: '35px', flexShrink: 0, visibility: onMenuClick ? 'visible' : 'hidden' }}>
            {onMenuClick && (
                <button
                    onClick={onMenuClick}
                    style={{
                        padding: '5px', // Smaller padding
                        backgroundColor: 'transparent',
                        border: 'none',
                        borderRadius: '50%',
                        cursor: 'pointer',
                        fontSize: isEasyMode ? '34px' : '26px', // Slightly larger menu icon
                        color: '#333',
                    }}
                    onMouseOver={e => e.currentTarget.style.color = '#1A73E8'}
                    onMouseOut={e => e.currentTarget.style.color = '#333'}
                >
                    <span role="img" aria-label="Menu">☰</span>
                </button>
            )}
        </div>
    </div>
);

export default HeaderBar;
